props.value:
computed(() => {
    if (this.accentColor() === 'default') {
      return '';
    }
    const attentionState = this.attention() ? 'attention' : 'subtle';
    return `nx-avatar--accent-${attentionState}-${this.accentColor()}`;
  })

computed<boolean>(() => {
    if (!this._wordsComponents()) {
      return false;
    }

    return this._wordsComponents().some((word) => word._hasErrors());
  })

effect(() => {
    const control = this.control() as any;

    // if aria-labelledby is set, add the word label to the list
    if (control.ariaLabelledBy !== null && control.ariaLabelledBy !== undefined) {
      control.ariaLabelledBy = `${this.labelId} ${control.ariaLabelledBy}`;
    }

    // if no aria-labelledby is set, we set it to the word label
    if (control.ariaLabelledBy === null) {
      control.ariaLabelledBy = this.labelId;
    }
  })

computed<string[]>(() => {
    // fallback to nlfError if describedBy is not set
    const useNaturalLanguageFormDescribedBy =
      this.describedByInput() === undefined && this._nlfErrorWrapper._errorId() !== undefined;
    const nlfError = useNaturalLanguageFormDescribedBy
      ? this._nlfErrorWrapper._errorId()
      : undefined;

    // fallback to the error children inside nx-word that is shown in the popover (deprecated)
    const errorChildren = this._errorChildren()?.map((error) => error.id);

    // ignore any undefined and null values
    return [nlfError, ...errorChildren, this.describedByInput()].filter(
      (id): id is string => id != null,
    );
  })

computed<string | null>(() => {
    this._errorState();
    // This is a workaround to not cause a breaking change for projected labels that are not wrapped in a label element.
    // if there is a projected label without a html label, we don't want to add the label id to the described by
    // should be removed with the next major version
    const hasProjectedLabelWithoutHtmlLabel =
      this.projectedLabelWrapper() && !this.projectedLabel();
    const hasDescribedBy = !!this.ariaDescribedBy() || this._isError();
    if (!hasDescribedBy && !hasProjectedLabelWithoutHtmlLabel) {
      return null;
    }

    const describedByIds = [
      ...(this._isError() ? this.errorMessages().map((e) => e.id) : []),
      this.ariaDescribedBy(),
    ];

    // Still the workaround for the projected label without html label
    // should be removed with the next major version
    if (hasProjectedLabelWithoutHtmlLabel) {
      describedByIds.push(this.labelId);
    }

    return describedByIds.join(' ');
  })

computed(() => {
    const hasLabelValue = !!this.label();
    const hasProjectedLabel = this.projectedLabelWrapper()?.nativeElement?.children?.length > 0;
    return hasLabelValue || hasProjectedLabel ? this.labelId : null;
  })

computed(() => {
    if (this._value() === null && (this.inputValue === '' || this.inputValue === this._value())) {
      return '';
    }
    let value = this._value() || '';

    const isInputChange = this._value() !== this.inputValue;
    if (isInputChange && this.nativeInput?.nativeElement?.value) {
      value = this.nativeInput?.nativeElement?.value || '';
    }

    // remove front zero
    let viewValue = this.removeFrontZero(value!.toString());

    // padding format
    viewValue = this.leadingZero() ? pad(viewValue!.toString(), 2) : viewValue!.toString();

    // decimal format
    viewValue = viewValue.replace(/[,.]/g, this.decimalSeperator);
    return viewValue;
  })

