props.value:
computed(() => {
    if (this.removable()) {
      return 'group';
    }
    if (this.tagList) {
      return 'button';
    }
    return null;
  })

effect(() => {
    this.selectionSubscriptions.unsubscribe();
    runInInjectionContext(this.injector, () => {
      this.selectionSubscriptions = merge(
        // the tiles use the new output method which are not observables anymore.
        // Angular provides the outputToObservable utility to convert them.
        ...this.tiles().map((tile) => outputToObservable(tile.selectionChange)),
      )
        .pipe(takeUntilDestroyed())
        .subscribe((value) => {
          if (this.selectionMode() === 'single') {
            // For single selection we can just take the value as there is no deselection possible.
            this.value.set(value);
          } else {
            const currentValue = this.value();
            // For multi selection we sync if the value is already in the state then it is a deselection and we remove it.
            if (Array.isArray(currentValue) && currentValue.includes(value)) {
              this.value.set(currentValue.filter((v: any) => v !== value));
            } else {
              this.value.set([...(currentValue || []), value]);
            }
          }
          this.onChange(this.value());
        });
    });
  })

computed(() => {
    if (Array.isArray(this.tileGroup.value())) {
      return this.tileGroup.value().includes(this.value());
    }
    return this.tileGroup.value() === this.value();
  })

computed(() => {
    const hintId = this.hint() ? `${this.id}-hint` : null;
    const errorIds = this.tileGroup._errorState() ? this.tileGroup.errorIds() : null;
    return [hintId, errorIds].filter(Boolean).join(' ') || null;
  })

computed(() => {
    if (!this.errorState() && !this.toggleGroup?.errorState() && !this.ariaDescribedBy()) {
      return null;
    }

    const errorMessageChildrenIds = this.errorChildren().map((errorMessage) => errorMessage.id);
    const toggleGroupDescribeBy = this.toggleGroup?.ariaDescribedBy();

    return [this.ariaDescribedBy(), errorMessageChildrenIds, toggleGroupDescribeBy].join(' ');
  })

computed(() => {
    if (this.errorState() && this.errorChildren().length > 0) {
      return this.errorChildren()
        .map((errorChild) => errorChild.id)
        .join(' ');
    }
    return null;
  })

computed<string | null>(() => {
    const input = this.ariaDescribedByInput();
    const formfield = this.ariaDescribedByFormfield();

    if (input && formfield) {
      return `${input}, ${formfield.join(' ')}`;
    } else if (input) {
      return input;
    }

    return formfield?.join(' ') || null;
  })

computed<string>(() => {
    const test = this.startDateAriaLabelInput() || this._intl.startDateAriaLabel();
    return test;
  })

computed<boolean>(() => {
    if (this.strictInputSignal() !== null) {
      return this.strictInputSignal()!;
    }

    if (this._dateStrict !== null && this._dateStrict !== undefined) {
      return this._dateStrict;
    }

    return true;
  })

computed<D | null>(() => {
    if (!!this._dayValue() && !!this._monthValue() && !!this._yearValue()) {
      const parsedDate = this._dateAdapter.parse(
        this._rawDateString(),
        this.format(),
        this.strict(),
      );

      return parsedDate;
    }

    return null;
  })

computed(() => {
    if (this._formFieldComponent) {
      return this._formFieldComponent.labelId;
    }
    return null;
  })

computed(() => {
    if (this.separatorInput() !== null) {
      return this.separatorInput();
    }

    const anyLetterRegex = /[a-z]/gi;
    const strippedFormat = this.format().replace(anyLetterRegex, '');

    if (strippedFormat.length > 0) {
      return strippedFormat[0];
    }

    return '.';
  })

effect(() => {
    const daysOccurances = [...this.format().matchAll(/(?=(D{2}))/g)];
    const monthOccurances = [...this.format().matchAll(/M{2}/g)];
    const yearOccurances = [...this.format().matchAll(/Y{4}/g)];

    if (
      daysOccurances.length !== 1 ||
      monthOccurances.length !== 1 ||
      yearOccurances.length !== 1
    ) {
      throw new Error(
        `Provided date format "${this.format()}" not an accepted format. Make sure to provide a complete Date formate with numeric values only and 4 digit years. `,
      );
    }
  })

computed<string>(() => {
    // remove any char that is not d|m|y
    const dmyRegex = /[^dmy]+/gi;
    let inputOrder = this.format().replace(dmyRegex, '');

    inputOrder = inputOrder.replace(/d+/i, 'd');
    inputOrder = inputOrder.replace(/m+/i, 'm');
    inputOrder = inputOrder.replace(/y+/i, 'y');

    return inputOrder;
  })

computed<string | null>(() => {
    const input = this.ariaDescribedByInput();
    const formfield = this.ariaDescribedByFormfield();

    if (input && formfield) {
      return `${input}, ${formfield.join(' ')}`;
    } else if (input) {
      return input;
    }

    return formfield?.join(' ') || null;
  })

computed(() => {
    if (this.disabledInput() !== undefined) {
      return this.disabledInput();
    }
    return this.datepicker.disabled() || false;
  })

computed(() => {
    if (this.disabledInput() !== undefined) {
      return this.disabledInput();
    }
    const inputsDisabled = this._registeredInputs().some(
      (input) => input.disabledSignal() || input.readonlyState(),
    );
    return inputsDisabled || false;
  })

(a: S, b: S) => {
    const aSelected = this._isOptionSelected(a);
    const bSelected = this._isOptionSelected(b);
    if (aSelected && !bSelected) {
      return -1;
    } else if (!aSelected && bSelected) {
      return 1;
    }
    return 0;
  }

{
    error: { icon: 'exclamation-triangle' },
    warning: { icon: 'exclamation-circle-warning' },
    success: { icon: 'check-circle' },
    info: { icon: 'info-circle' },
  }

